'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameComplex128Array = require( '@stdlib/assert/is-same-complex128array' );
var Complex128Array = require( '@stdlib/array/complex128' );
var zediff = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof zediff, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 15', function test( t ) {
	t.strictEqual( zediff.length, 15, 'returns expected value' );
	t.end();
});

tape( 'the function calculates differences between consecutive elements of a double-precision complex floating-point strided array', function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;
	var o;

	x = new Complex128Array([
		4.0,
		4.0,
		8.0,
		8.0,
		12.0,
		12.0,
		16.0,
		16.0,
		20.0,
		20.0
	]);
	p = new Complex128Array([
		10.0,
		10.0,
		15.0,
		15.0
	]);
	a = new Complex128Array([
		30.0,
		30.0,
		35.0,
		35.0
	]);
	o = new Complex128Array( 8 );

	out = zediff( x.length, x, 1, 0, 2, p, 1, 0, 2, a, 1, 0, o, 1, 0 );

	expected = new Complex128Array([
		10.0,
		10.0,
		15.0,
		15.0,
		4.0,
		4.0,
		4.0,
		4.0,
		4.0,
		4.0,
		4.0,
		4.0,
		30.0,
		30.0,
		35.0,
		35.0
	]);
	t.strictEqual( isSameComplex128Array( o, expected ), true, 'returns expected value' );
	t.strictEqual( out, o, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns the output array unchanged', function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;

	x = new Complex128Array([
		2.0,
		-2.0,
		4.0,
		-4.0
	]);
	p = new Complex128Array( 0 );
	a = new Complex128Array( 0 );
	out = new Complex128Array( 2 );

	zediff( 0, x, 1, 0, 0, p, 1, 0, 0, a, 1, 0, out, 1, 0 );

	expected = new Complex128Array([
		0.0,
		0.0,
		0.0,
		0.0
	]);
	t.strictEqual( isSameComplex128Array( out, expected ), true, 'returns expected value' );

	zediff( -4, x, 1, 0, 0, p, 1, 0, 0, a, 1, 0, out, 1, 0 );
	t.strictEqual( isSameComplex128Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'if the sum of the `N`, `N1`, and `N2` parameters is less than or equal to `1`, the function returns the output array unchanged', function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;

	x = new Complex128Array([
		5.0,
		-5.0
	]);
	p = new Complex128Array( 0 );
	a = new Complex128Array( 0 );
	out = new Complex128Array( 1 );

	zediff( 1, x, 1, 0, 0, p, 1, 0, 0, a, 1, 0, out, 1, 0 );

	expected = new Complex128Array([
		0.0,
		0.0
	]);
	t.strictEqual( isSameComplex128Array( out, expected ), true, 'returns expected value' );
	t.end();
});

