tape( 'the function supports multiple prepend and append values', function test( t ) {
	var expected;
	var x;
	var p;
	var a;
	var o;

	// Prepend (N1=2), x, and append (N2=2):
	x = new Complex128Array([
		5.0,
		-5.0
	]);
	p = new Complex128Array([
		1.0,
		-1.0,
		3.0,
		-3.0
	]);
	a = new Complex128Array([
		7.0,
		-7.0,
		9.0,
		-9.0
	]);
	o = new Complex128Array( 4 );

	zediff( x.length, x, 1, 0, 2, p, 1, 0, 2, a, 1, 0, o, 1, 0 );

	expected = new Complex128Array([
		1.0,
		-1.0,
		3.0,
		-3.0,
		7.0,
		-7.0,
		9.0,
		-9.0
	]);
	t.strictEqual( isSameComplex128Array( o, expected ), true, 'returns expected value' );

	// Prepend (N1=2) and append (N2=2), no x:
	x = new Complex128Array( 0 );
	o = new Complex128Array( 4 );

	zediff( 0, x, 1, 0, 2, p, 1, 0, 2, a, 1, 0, o, 1, 0 );

	expected = new Complex128Array([
		1.0,
		-1.0,
		3.0,
		-3.0,
		7.0,
		-7.0,
		9.0,
		-9.0
	]);
	t.strictEqual( isSameComplex128Array( o, expected ), true, 'returns expected value' );
	t.end();
});

