tape( 'the function supports multiple append values without prepend', function test( t ) {
	var expected;
	var x;
	var p;
	var a;
	var o;

	// No prepend, x present, multiple append (N2=3):
	x = new Complex128Array([
		2.0,
		-2.0,
		5.0,
		-5.0
	]);
	p = new Complex128Array( 0 );
	a = new Complex128Array([
		10.0,
		-10.0,
		13.0,
		-13.0,
		18.0,
		-18.0
	]);
	o = new Complex128Array( 4 );

	zediff( x.length, x, 1, 0, 0, p, 1, 0, 3, a, 1, 0, o, 1, 0 );

	expected = new Complex128Array([
		3.0,
		-3.0,
		10.0,
		-10.0,
		13.0,
		-13.0,
		18.0,
		-18.0
	]);
	t.strictEqual( isSameComplex128Array( o, expected ), true, 'returns expected value' );

	// Append only (no prepend, no x):
	x = new Complex128Array( 0 );
	o = new Complex128Array( 3 );

	zediff( 0, x, 1, 0, 0, p, 1, 0, 3, a, 1, 0, o, 1, 0 );

	expected = new Complex128Array([
		10.0,
		-10.0,
		13.0,
		-13.0,
		18.0,
		-18.0
	]);
	t.strictEqual( isSameComplex128Array( o, expected ), true, 'returns expected value' );
	t.end();
});

